# -*- coding: utf-8 -*-
import logging

from taf.fdsw.rc.interfaces.FDSW19.autoconnection import AutoConfiguration19
from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import \
    AutoconnectionParametersBuilder19A

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoConfiguration19A(AutoConfiguration19):
    param_builder = AutoconnectionParametersBuilder19A

    def set_autoconnection(self, timeout, **kwargs):
        parameters = self.param_builder(**kwargs).as_dict()
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters=parameters)
